// The Wi-Fi setup screen with this device's own access-point password and its QR code.
//
// The picture is the approved one (Software/mockups/portal_v4.png) with the QR code and the password
// line taken out (portal_art.h, generated by Software/mockups/portal_art.py); both are drawn back here
// for the password this device actually uses. No ESP-IDF dependency, so it builds on the host too.
#pragma once
#include <cstddef>
#include <cstdint>

namespace PortalScreen {

constexpr size_t kPlaneBytes = 15000;   // one 4-gray plane: 400 x 300, 1 bit a pixel

// Fills p24/p26 (kPlaneBytes each) with the setup screen for this network. False when the QR code
// cannot be made or a password character has no glyph; the planes then hold the bare picture.
bool compose(uint8_t *p24, uint8_t *p26, const char *ssid, const char *password);

// The battery in the top-right corner, where the dashboard has it and drawn the same way: outline,
// fill, percent in Org_01, the plug while the cable is in, the bolt while it charges. percent is
// 0..100, or -1 for "no figure" — on the charger the voltage is the charger's, not the cell's, and
// the caller shows the plug and the bolt instead of a number nobody can vouch for. Below 15 % on
// battery the figure turns white in a black pill, as on the dashboard. Draws over whatever the
// planes hold; the setup picture is white in that corner.
struct Battery {
    int  percent  = -1;
    bool usb      = false;
    bool charging = false;
};
void drawBattery(uint8_t *p24, uint8_t *p26, const Battery &b);

// Just the picture, with no QR code and no password: the fallback when compose() refuses. Fills the
// caller's planes rather than returning pointers — the artwork ships compressed, so there is no
// plain copy in flash to point at.
bool expandArt(uint8_t *p24, uint8_t *p26);

} // namespace PortalScreen
